  CW += c[42] * 5.2075999999999993e+01; // C4H4
  CW += c[43] * 5.3083999999999996e+01; // iC4H5
  CW += c[44] * 5.3083999999999996e+01; // C4H5-2
  CW += c[45] * 5.4091999999999999e+01; // C4H6
