  CW += c[54] * 7.0134999999999991e+01; // C5H10
  CW += c[55] * 2.8013999999999999e+01; // N2
  // Now compute conversion
  amrex::Real CWinv = 1.0 / CW;
  y[0] = c[0] * 1.0080000000000000e+00 * CWinv;
