  // reaction 20: H + H2O2 <=> H2O + OH
  qf[46] = sc[0] * sc[6];
  qr[46] = sc[2] * sc[5];

  // reaction 21: H2O2 + O <=> HO2 + OH
  qf[47] = sc[1] * sc[6];
  qr[47] = sc[2] * sc[3];

  // reaction 22: H2O2 + OH <=> H2O + HO2
