  // reaction 7:  H + O + M <=> OH + M
  k_f = 9428000 * exp((-1) * logT);
  Corr = mixture + sc[4] + (11) * sc[5] + (0.75) * sc[18] + (2.6) * sc[19];
  qf[29] *= Corr * k_f;
